package com.example.cidashboard.controller;
import com.example.cidashboard.model.PipelineRun; import com.example.cidashboard.service.PipelineService; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") @CrossOrigin(origins="*") public class ApiController {
 private final PipelineService pipelines; public ApiController(PipelineService p){pipelines=p;}
 @GetMapping("/dashboard/summary") public Map<String,Object> summary(){var r=pipelines.all();long pass=r.stream().filter(x->x.status().equals("PASSED")).count();long fail=r.stream().filter(x->x.status().equals("FAILED")).count();long completed=pass+fail;long seconds=r.stream().filter(x->x.status().equals("PASSED")||x.status().equals("FAILED")).mapToLong(PipelineRun::durationSeconds).sum();return Map.of("totalRuns",r.size(),"successfulBuilds",pass,"failedBuilds",fail,"passRate",completed==0?0:Math.round(100.0*pass/completed),"averageDurationSeconds",seconds/Math.max(1,completed),"latest",r.get(0),"dataMode","DEMO");}
 @GetMapping("/pipelines") public List<PipelineRun> pipelines(){return pipelines.all();}
 @GetMapping("/pipelines/{id}") public ResponseEntity<?> pipeline(@PathVariable String id){return pipelines.get(id).<ResponseEntity<?>>map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());}
 public record RunRequest(@NotBlank String branch,@NotBlank String triggeredBy){}
 @PostMapping("/pipelines/run") public ResponseEntity<PipelineRun> run(@Valid @RequestBody RunRequest req){return ResponseEntity.accepted().body(pipelines.run(req.branch(),req.triggeredBy()));}
 @GetMapping("/tests/results") public Map<String,Object> tests(){return Map.of("mode","DEMO","suites",List.of(Map.of("name","Unit tests","passed",32,"failed",0,"durationSeconds",2.4,"framework","JUnit 5 + Mockito"),Map.of("name","Integration tests","passed",8,"failed",0,"durationSeconds",7.1,"framework","Spring Boot Test + MockMvc"),Map.of("name","Contract tests","passed",2,"failed",0,"durationSeconds",1.8,"framework","Pact JVM"),Map.of("name","Container tests","passed",0,"failed",0,"durationSeconds",0,"framework","Testcontainers (optional; Docker required)")));}
 @GetMapping("/services") public List<Map<String,Object>> services(){return List.of(Map.of("name","Product Service","method","GET","path","/api/products/{id}","status",200,"response",Map.of("id","p-101","name","Build Monitor","price",29.99)),Map.of("name","Order Service","method","POST","path","/api/orders","status",201,"response",Map.of("id","o-204","productId","p-101","quantity",2)));}
 @GetMapping("/deployment/instance") public Map<String,String> deploymentInstance(){return Map.of("slot",System.getenv().getOrDefault("APP_DEPLOYMENT_SLOT","local"),"version",System.getenv().getOrDefault("APP_VERSION","dev"));}
 @GetMapping("/products/{id}") public ResponseEntity<?> product(@PathVariable String id){if(!id.equals("p-101"))return ResponseEntity.notFound().build();return ResponseEntity.ok(Map.of("id","p-101","name","Build Monitor","price",29.99));}
 public record OrderRequest(@NotBlank String productId, @jakarta.validation.constraints.Min(1) int quantity){}
 @PostMapping("/orders") public ResponseEntity<?> order(@Valid @RequestBody OrderRequest req){if(!req.productId().equals("p-101"))return ResponseEntity.status(422).body(Map.of("error","Product not found"));return ResponseEntity.status(201).body(Map.of("id","o-"+UUID.randomUUID().toString().substring(0,8),"productId",req.productId(),"quantity",req.quantity()));}
}
